const exampleCards=(items=examples)=>`<div class="photo-grid">${items.map(v=>`<article class="photo-card"><div class="pic">${photo(v[0],v[2])}<span>${v[1]}</span></div><div class="copy">${icon(iconFor(v[2]))}<h3>${v[2]}</h3><p>${v[3]}</p><div class="deliver"><strong>Example deliverables</strong>${v[4]}</div>${link('business','Discuss a project','textlink')}</div></article>`).join('')}</div>${imageNote}`;
const photoServices=(items,keys,category='Service')=>`<div class="photo-grid">${items.map((v,i)=>`<article class="photo-card"><div class="pic">${photo(keys[i],v[0])}<span>${category} ${String(i+1).padStart(2,'0')}</span></div><div class="copy"><h3>${v[0]}</h3><p>${v[1]}</p>${v[2]?`<ul class="list">${v[2].map(x=>`<li>${x}</li>`).join('')}</ul>`:''}</div></article>`).join('')}</div>`;
const visualPh=(label,title,desc,actions,keys)=>`<section class="pagehero visual-banner"><div class="wrap"><div><div class="crumb"><a href="#home">Home</a> / ${label}</div><div class="eyebrow">${label}</div><h1>${title}</h1><p>${desc}</p><div class="actions">${actions}</div></div><div class="banner-photos">${keys.map(k=>photo(k,`Illustrative ${k} business scene`,'eager')).join('')}</div></div></section>`;
const mosaic=()=>`<div class="hero-mosaic">${[['team','Digital campaigns'],['live','Live commerce'],['tech','Technology & data'],['trade','Global trade']].map(v=>`<figure>${photo(v[0],v[1],'eager')}<figcaption>${v[1]}</figcaption></figure>`).join('')}</div>`;

const svg=(type)=>{const common=`<defs><pattern id="g${type}" width="24" height="24" patternUnits="userSpaceOnUse"><path d="M24 0H0V24" stroke="#ffffff" stroke-opacity=".08" fill="none"/></pattern></defs><rect width="420" height="200" fill="url(#g${type})"/>`;let s='';if(type==='tech'){s=`<g stroke="#7dd5f2" stroke-width="2" fill="#203e59"><rect x="53" y="46" width="102" height="113" rx="8"/><rect x="168" y="33" width="102" height="126" rx="8"/><rect x="283" y="60" width="84" height="99" rx="8"/></g><g fill="#b4e9f3">${[65,180,295].map((x,i)=>[80,105,130].map(y=>`<rect x="${x}" y="${y}" width="${i===2?60:78}" height="8" rx="2" opacity=".7"/><circle cx="${x+8}" cy="${y+4}" r="2" fill="#16354d"/>`).join('')).join('')}</g><path d="M35 173H386" stroke="#72b7da" stroke-opacity=".6"/>`;}else if(type==='trade'){s=`<g fill="none" stroke="#b1d8ea" opacity=".5"><ellipse cx="210" cy="96" rx="133" ry="76"/><ellipse cx="210" cy="96" rx="72" ry="76"/><ellipse cx="210" cy="96" rx="133" ry="34"/><path d="M77 96H343M210 20V172"/></g><path d="M105 117Q191 18 309 72M142 52Q215 150 330 121" stroke="#9ce9da" stroke-width="2" stroke-dasharray="5 5" fill="none"/><g fill="#9ce9da"><circle cx="105" cy="117" r="6"/><circle cx="309" cy="72" r="6"/><circle cx="142" cy="52" r="6"/><circle cx="330" cy="121" r="6"/></g><g fill="#1c455b" stroke="#a8d8e4"><rect x="163" y="102" width="96" height="45" rx="3"/><path d="M163 115H259M179 102V147M242 102V147"/></g>`;}else{s=`<g fill="#342f59" stroke="#b5a4f3"><rect x="92" y="19" width="96" height="160" rx="13"/><rect x="102" y="37" width="76" height="115" rx="4" fill="#6654b7"/><circle cx="140" cy="164" r="4"/></g><circle cx="140" cy="76" r="19" fill="#f0b9a5"/><path d="M111 132Q110 97 140 97Q170 97 170 132" fill="#bfe8e1"/><g fill="#39365d" stroke="#b5a4f3"><rect x="208" y="36" width="131" height="66" rx="7"/><rect x="208" y="114" width="131" height="49" rx="7"/></g><path d="M223 84L249 69L270 77L318 52" fill="none" stroke="#9ce9da" stroke-width="3"/><g fill="#c9baff"><rect x="223" y="128" width="95" height="5" rx="2"/><rect x="223" y="141" width="62" height="5" rx="2" opacity=".6"/></g><circle cx="189" cy="31" r="11" fill="#9ce9da"/><path d="M184 31L188 35L195 27" stroke="#302d53" fill="none" stroke-width="2"/>`;}return `<svg viewBox="0 0 420 200" role="img" aria-label="${type==='tech'?'Server infrastructure':type==='trade'?'Global supply network':'Creator content and marketing analytics'}">${common}${s}</svg>`};
const heroArt=`<svg viewBox="0 0 530 460" role="img" aria-label="Connected ecosystem of technology infrastructure, global trade and digital creator services"><defs><linearGradient id="glow" x1="0" y1="0" x2="1" y2="1"><stop stop-color="#2b6384"/><stop offset="1" stop-color="#162d47"/></linearGradient><pattern id="heroGrid" width="32" height="32" patternUnits="userSpaceOnUse"><path d="M32 0H0V32" fill="none" stroke="#a5d0ea" stroke-opacity=".09"/></pattern></defs><rect x="0" y="0" width="530" height="460" rx="22" fill="url(#heroGrid)"/><g fill="none" stroke="#8ac9db" stroke-opacity=".25"><circle cx="265" cy="229" r="191"/><circle cx="265" cy="229" r="150"/><circle cx="265" cy="229" r="112"/></g><g stroke="#9ce9da" stroke-width="1.7" fill="none" stroke-dasharray="5 6"><path d="M265 229L126 111M265 229L404 131M265 229L295 362"/></g><g fill="#9ce9da"><circle cx="265" cy="229" r="5"/><circle cx="126" cy="111" r="4"/><circle cx="404" cy="131" r="4"/><circle cx="295" cy="362" r="4"/></g><g><rect x="192" y="171" width="146" height="116" rx="16" fill="url(#glow)" stroke="#9ce9da"/><path d="M219 235V201H230L265 231L300 201H311V235H301V216L265 246L229 216V235Z" fill="#d9f9f2"/><text x="265" y="266" fill="#d9f9f2" text-anchor="middle" font-size="12" font-weight="700" letter-spacing="2">MINDARC</text></g><g><rect x="30" y="39" width="193" height="104" rx="11" fill="#203e59" stroke="#7ca8c2"/><text x="47" y="62" font-size="10" fill="#9ce9da" letter-spacing="1.2">01 / TECHNOLOGY</text><g stroke="#a8ddf1" fill="none"><rect x="48" y="76" width="41" height="44" rx="4"/><path d="M55 88H82M55 98H82M55 108H82"/></g><text x="101" y="92" fill="#fff" font-weight="700" font-size="15">Cloud &amp; Data</text><text x="101" y="111" fill="#c5d7e6" font-size="10">Intelligent infrastructure</text></g><g><rect x="316" y="71" width="197" height="104" rx="11" fill="#203e59" stroke="#7ca8c2"/><text x="333" y="94" font-size="10" fill="#9ce9da" letter-spacing="1.2">02 / COMMERCE</text><g stroke="#a8ddf1" fill="none"><circle cx="354" cy="130" r="19"/><ellipse cx="354" cy="130" rx="8" ry="19"/><path d="M335 130H373M340 119H368M340 141H368"/></g><text x="384" y="126" fill="#fff" font-weight="700" font-size="15">Global Trade</text><text x="384" y="145" fill="#c5d7e6" font-size="10">Connected supply chains</text></g><g><rect x="157" y="320" width="277" height="112" rx="11" fill="#33395f" stroke="#a8a4ec"/><text x="175" y="344" font-size="10" fill="#d4cbff" letter-spacing="1.2">03 / CREATOR ECONOMY</text><g stroke="#d4cbff" fill="none"><rect x="176" y="358" width="35" height="55" rx="6"/><path d="M188 373L202 382L188 391Z" fill="#d4cbff"/><path d="M181 405H206"/></g><text x="225" y="379" fill="#fff" font-weight="700" font-size="16">Digital Marketing</text><text x="225" y="399" fill="#ded8ff" font-size="11">Creators · Content · Live commerce</text></g></svg>`;
const divisions=[{id:'technology',n:'01 / Technology',title:'Technology & Data',desc:'Build scalable digital infrastructure, turn data into insight and improve business operations.',items:['Data services & data consulting','Business intelligence & advanced analytics','Cloud services & IT consulting'],type:'tech'},{id:'trade',n:'02 / Commerce',title:'Global Trade & Hardware',desc:'Connect with international suppliers and coordinate the sourcing and distribution of technology equipment.',items:['IT hardware procurement','International import & export','Supply chain & logistics coordination'],type:'trade'},{id:'marketing',n:'03 / Growth',title:'Digital Marketing & Creators',desc:'Reach audiences with digital campaigns, creator-led content and flexible independent talent.',items:['Digital advertising & influencer campaigns','Content, reviews & livestream commerce','Freelancer & affiliate collaborations'],type:'creator'}];
