const policies={privacy:['Privacy notice',[['Website preview','This prototype does not transmit form information to a server. Information entered in the forms is used locally to prepare an email draft; sending that draft is a separate action in your email application.'],['Information and purposes','For an implemented service, business contact details and creator profile information may be collected to respond to inquiries, evaluate applications and administer projects. The final notice must reflect actual collection, processing, sharing, retention and security arrangements.'],['Contact','Privacy inquiries may be directed to mindarc.limited@gmail.com.']]],terms:['Website terms',[['Website information','This website prototype presents proposed business services and collaboration opportunities. An inquiry or application does not establish a binding service relationship.'],['Commercial engagements','Projects are subject to separate agreements specifying scope, fees, acceptance criteria, responsibilities and delivery terms.'],['Creator participation','Applications do not guarantee assignments, employment or income. The legal status of an engagement depends on the actual working arrangements and applicable law.']]],cookies:['Cookie notice',[['Prototype technology','This self-contained prototype does not set cookies or use third-party analytics scripts.'],['Production website','The final website must identify cookies and similar technologies actually used, their purposes, retention periods and applicable consent controls.']]],standards:['Creator & advertising standards',[['Authentic content','Reviews and experience-based content must reflect genuine experiences. Positive reviews may not be required, and incentivized public reviews are not allowed where the platform prohibits them.'],['Commercial disclosures','Sponsored content and commercial relationships must be clearly disclosed in line with applicable laws and platform requirements.'],['Content and rights','Respect intellectual property, privacy, confidentiality and agreed content licensing arrangements.'],['Performance integrity','Fake accounts, artificial engagement, fabricated transactions and falsified metrics are prohibited. Compensation must relate to genuine services or verified performance.'],['Project conduct','Creators must meet accepted deliverable requirements. Restricted products and promotional activities are subject to review and applicable rules.']]]};
Object.entries(policies).forEach(([key,v])=>pages[key]=()=>ph('Company policies',v[0],'Information for responsible and transparent collaboration.')+sec(`<div class="legal"><div class="note">Draft for review before production launch.</div>${v[1].map(x=>`<h3>${x[0]}</h3><p>${x[1]}</p>`).join('')}</div>`));

