const titles={home:'Technology. Commerce. Growth.',technology:'Technology & Data Solutions',trade:'Global Trade & Hardware',marketing:'Digital Marketing & Creator Economy',creators:'Creator Network',business:'Start a Project',apply:'Join as a Creator',about:'About Us',contact:'Contact',industries:'Industries',showcases:'Solution Showcases',faq:'Frequently Asked Questions',privacy:'Privacy Notice',terms:'Website Terms',cookies:'Cookie Notice',standards:'Creator & Advertising Standards'};
function render(){const hash=location.hash.slice(1)||'home';if(hash==='main')return;const page=Object.hasOwn(pages,hash)?hash:'home';document.getElementById('main').innerHTML=pages[page]();document.title=`MindArc | ${titles[page]}`;document.querySelectorAll('.navlinks a').forEach(a=>{const active=a.getAttribute('href')==='#'+page;a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});document.getElementById('navlinks').classList.remove('open');document.getElementById('menu').setAttribute('aria-expanded','false');window.scrollTo(0,0);document.querySelectorAll('form[data-kind]').forEach(f=>f.addEventListener('submit',e=>{e.preventDefault();if(!f.reportValidity())return;const subject={business:'Business project inquiry',apply:'Creator network application',contact:'Website contact inquiry'}[f.dataset.kind];const body='Dear MindArc team,\n\n'+Array.from(new FormData(f).entries()).map(([k,v])=>`${k}: ${v}`).join('\n')+'\n\nThank you.';const out=f.querySelector('.output');out.hidden=false;out.querySelector('pre').textContent=body;out.querySelector('[data-mail]').href=`mailto:mindarc.limited@gmail.com?subject=${encodeURIComponent(subject)}&body=${encodeURIComponent(body)}`;out.querySelector('[data-copy]').onclick=async()=>{try{await navigator.clipboard.writeText(body);out.querySelector('[data-status]').textContent='Copied.'}catch(err){out.querySelector('[data-status]').textContent='Select and copy the draft text above.'}};out.scrollIntoView({behavior:'smooth',block:'nearest'})}));}
document.getElementById('menu').addEventListener('click',()=>{const nav=document.getElementById('navlinks');const open=nav.classList.toggle('open');document.getElementById('menu').setAttribute('aria-expanded',String(open))});window.addEventListener('hashchange',render);render();
